using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

static partial class OpenTypeReader {
 public static int[] UnicodePoints(FontRecord record){byte[] b=Face(record);var tables=Tables(b,0);if(!tables.ContainsKey("cmap"))return new int[0];int root=tables["cmap"][0],tableEnd=root+tables["cmap"][1];if(root+4>tableEnd)return new int[0];int count=U16(b,root+2);var points=new SortedSet<int>();for(int n=0;n<count;n++){int entry=root+4+n*8;if(entry+8>tableEnd)break;int platform=U16(b,entry),encoding=U16(b,entry+2);if(platform!=0&&!(platform==3&&(encoding==0||encoding==1||encoding==10)))continue;int rel=I32(b,entry+4);if(rel<0||rel>tableEnd-root-2)continue;int start=root+rel,format=U16(b,start);try{if(format==12){if(start+16>tableEnd)continue;int length=I32(b,start+4),groups=I32(b,start+12);if(length<16||(long)start+length>tableEnd||groups<0||groups>100000)continue;for(int j=0;j<groups;j++){int p=start+16+j*12;if(p+12>start+length)break;int first=I32(b,p),last=I32(b,p+4),glyph=I32(b,p+8);if(first<0||last<first||last>0x10ffff)continue;for(int cp=first;cp<=last&&points.Count<150000;cp++)if((long)glyph+cp-first>0&&Printable(cp))points.Add(cp);}}else if(format==4){if(start+14>tableEnd)continue;int length=U16(b,start+2),segments=U16(b,start+6)/2,end=start+14,beg=end+segments*2+2,delta=beg+segments*2,ranges=delta+segments*2;if(segments<1||segments>32768||start+length>tableEnd||ranges+segments*2>start+length)continue;for(int j=0;j<segments;j++){int lo=U16(b,beg+j*2),hi=U16(b,end+j*2),d=U16(b,delta+j*2),offset=U16(b,ranges+j*2);for(int cp=lo;cp<=hi;cp++){if(!Printable(cp)||cp==65535)continue;int glyph;if(offset==0)glyph=(cp+d)&65535;else{int at=ranges+j*2+offset+2*(cp-lo);if(at<start||at+2>start+length)continue;glyph=U16(b,at);if(glyph!=0)glyph=(glyph+d)&65535;}if(glyph!=0)points.Add(cp);}}}}catch{} }return points.ToArray();}
 static bool Printable(int cp){return cp>=32&&cp<=0x10ffff&&!(cp>=0x7f&&cp<=0x9f)&&!(cp>=0xd800&&cp<=0xdfff);}
}
partial class Desktop {
 async Task GetFontGlyphs(string id,string fontId){FontRecord face;lock(fontLock)face=packageFaces.Concat(fontCatalog).FirstOrDefault(f=>f.id==fontId);if(face==null)throw new Exception("La fuente no está disponible en el catálogo.");var points=await Task.Run(()=>OpenTypeReader.UnicodePoints(face));Reply(id,new{fontId=fontId,points=points,family=face.family,style=face.style});}
}
